    11	/** Gamma-encoded luma, 0..1: the quantity ffmpeg's blackdetect compares with its pixel threshold. */
    12	function luma(hex: string): number {
    13	  const m = /^#([0-9a-f]{2})([0-9a-f]{2})([0-9a-f]{2})$/i.exec(hex);
    14	  if (!m) throw new Error(`not a #rrggbb colour: ${hex}`);
    15	  const [r, g, b] = [m[1]!, m[2]!, m[3]!].map((c) => parseInt(c, 16) / 255) as [number, number, number];
    16	  return 0.299 * r + 0.587 * g + 0.114 * b;
    17	}
