    22	/** A mono 16-bit WAV holding a 440 Hz tone, the format the voice stage writes. */
    23	function writeTone(path: string, seconds: number, sampleRate = 24000): void {
    24	  const samples = Math.round(seconds * sampleRate);
    25	  const buf = Buffer.alloc(44 + samples * 2);
    26	  buf.write('RIFF', 0); buf.writeUInt32LE(36 + samples * 2, 4); buf.write('WAVE', 8);
    27	  buf.write('fmt ', 12); buf.writeUInt32LE(16, 16); buf.writeUInt16LE(1, 20); buf.writeUInt16LE(1, 22);
    28	  buf.writeUInt32LE(sampleRate, 24); buf.writeUInt32LE(sampleRate * 2, 28); buf.writeUInt16LE(2, 32); buf.writeUInt16LE(16, 34);
    29	  buf.write('data', 36); buf.writeUInt32LE(samples * 2, 40);
    30	  for (let n = 0; n < samples; n++) buf.writeInt16LE(Math.round(Math.sin((2 * Math.PI * 440 * n) / sampleRate) * 12000), 44 + n * 2);
    31	  writeFileSync(path, buf);
    32	}
