    22	    expect(luma(theme.color.bg)).toBeGreaterThanOrEqual(0.12);
    23	    expect(luma(theme.color.bgGlow)).toBeGreaterThanOrEqual(0.12);
    24	    expect(theme.backdrop).toContain(theme.color.bg);
    25	  });
    26	
