// The seven video frames, each a 1920x1080 SVG. Returned as { defs, body, label } so they can also be used as posters.
import { f, ringD, crossD, qD, underD, pencil, hstrip, greek, loupe, refract, esc } from './lib.mjs';

const bgDefs = (id, x, y) => `<radialGradient id="${id}" cx="${x}" cy="${y}" r="1300" gradientUnits="userSpaceOnUse"><stop offset="0" stop-color="#1e2a26"/><stop offset=".45" stop-color="#141c1a"/><stop offset="1" stop-color="#0c1110"/></radialGradient>`;
const bg = (id) => `<rect width="1920" height="1080" fill="url(#${id})"/>`;
const spill = (x, y, r) => `<circle cx="${f(x)}" cy="${f(y)}" r="${f(r)}" fill="url(#spillG)"/>`;
const T = (cls, x, y, size, text, o = {}) => {
  const { w = 400, fill = '#eef3f1', op = 1, anchor = '', ls = 0, extra = '' } = o;
  return `<text class="${cls}" x="${f(x)}" y="${f(y)}" font-size="${size}" font-weight="${w}" fill="${fill}"${op < 1 ? ` fill-opacity="${op}"` : ''}${anchor ? ` text-anchor="${anchor}"` : ''}${ls ? ` letter-spacing="${ls}"` : ''}${extra ? ' ' + extra : ''}>${text}</text>`;
};
const lensLit = `<circle r="1200" fill="url(#pic)"/><circle r="1200" fill="#2a3f38"/>`;

/* 1 — title ------------------------------------------------------------ */
export function title({ poster = false, p = 'ti' } = {}) {
  const lx = 600, ly = 690, s = 1.4;
  const yc = ly - (lx - 960) * Math.tan((-2 * Math.PI) / 180);
  const S = hstrip({ id: p + 's', P: 300, x0: lx - 750, y0: yc - 138.2, k0: -2, k1: 8, rot: -2, rcx: 960, rcy: yc, frame: '#101816' });
  let fr = '';
  for (let k = -1; k <= 7; k++) fr += greek(S.fx(k) + 26, S.fy + 34, S.fw - 60, S.fh, 40 + k, { bar: 8, op: 0.09 });
  for (let k = 3; k <= 6; k++) fr += T('mono', S.fx(k) + 2, S.bottom - 4, 9.5, `${k + 1}A`, { op: 0.4, ls: 1 });
  fr += T('mono', S.fx(4) + 60, S.top + 11, 9.5, 'DAILIES SAFETY FILM', { op: 0.3, ls: 2.4 });
  const strip = S.open + S.body + fr + S.close;

  const lens = poster
    ? `${lensLit}<circle r="124" fill="#ffd60a"/><path d="M-30,-50 L52,0 L-30,50Z" fill="#0d1211" stroke="#0d1211" stroke-width="12" stroke-linejoin="round"/>${T('mono', 0, 212, 34, '1:14', { w: 500, anchor: 'middle', op: 0.85 })}`
    : `${lensLit}<g fill="#eef3f1" opacity=".14"><rect x="-196" y="-268" width="190" height="14" rx="7"/><rect x="-196" y="-234" width="292" height="14" rx="7"/><rect x="-150" y="212" width="240" height="14" rx="7"/><rect x="-150" y="246" width="150" height="14" rx="7"/></g>${T('disp', 0, 40, 112, 'acme/api', { w: 800, anchor: 'middle', ls: -2 })}`;

  const text = poster
    ? T('disp', 1192, 232, 106, 'acme/api', { w: 800, ls: -2 }) + T('disp', 1196, 316, 45, 'last night, 23:40 – 06:10', { w: 300, fill: '#c3cfca' })
    : T('disp', 1186, 250, 124, 'last night', { w: 300 }) + T('disp', 1192, 360, 80, '23:40 – 06:10', { w: 600 });

  return {
    label: poster ? 'Poster. acme/api, last night, 23:40 to 06:10. A loupe on a strip of film; the lens holds the play button. 1:14.' : 'Title. Dailies. acme/api, last night, 23:40 to 06:10. A loupe rests on the first frame of a strip of film.',
    defs: bgDefs(p + 'bg', lx, ly) + S.defs,
    body: bg(p + 'bg') + strip + spill(lx, ly, 900) + loupe({ x: lx, y: ly, s, lens, under: refract(S.id, lx, ly) }) + T('disp', 96, 124, 40, 'Dailies', { w: 600, ls: -0.5 }) + text,
  };
}

/* 2 — prompt ----------------------------------------------------------- */
export function prompt() {
  const lx = 960, ly = 540, s = 2.25;
  const S = hstrip({ id: 'ps', P: 1100, x0: 410, y0: 33, k0: -1, k1: 1, rot: -2, rcx: 960, rcy: 540, frame: '#101816' });
  const strip = S.open + S.body + greek(S.fx(-1) + 760, S.fy + 150, 400, 300, 8, { bar: 22, op: 0.08, n: 5 }) + greek(S.fx(1) + 70, S.fy + 380, 300, 300, 9, { bar: 22, op: 0.08, n: 5 }) + S.close;
  const fs = 68, k = fs / 100, L = [['Add retry with backoff', 1309.2], ['to the webhook sender, and', 1600], ['make sure the tests cover', 1505.3], ['the timeout path.', 1006.1]];
  const ys = [-112, -22, 68, 158];
  const lines = L.map(([t], i) => T('disp', 0, ys[i], fs, t, { w: 300, anchor: 'middle' })).join('');
  const u1x = (-L[0][1] / 2 + 265.2) * k, u1w = 1044.1 * k;
  const u2x = (-L[3][1] / 2 + 221.3) * k, u2w = 763.2 * k;
  const marks = pencil([underD(u1x - 6, u1x + u1w + 8, ys[0] + 21, { seed: 2, amp: 5 }), underD(u2x - 6, u2x + u2w + 6, ys[3] + 21, { seed: 6, amp: 5 })], { sw: 9, pad: `M${f(u1x)},${ys[0] - 40}V${ys[3] + 80}` });
  const lens = `${lensLit}<g transform="rotate(-2)">${T('txt', 0, -236, 38, 'You asked', { w: 600, anchor: 'middle', fill: '#c3cfca' })}${lines}${marks}${T('mono', 0, 262, 24, 'session 1 · 23:40', { anchor: 'middle', op: 0.5, ls: 1 })}</g>`;
  return {
    label: 'Prompt. You asked: Add retry with backoff to the webhook sender, and make sure the tests cover the timeout path.',
    defs: bgDefs('pbg', lx, ly) + S.defs,
    body: bg('pbg') + strip + spill(lx, ly, 1300) + loupe({ x: lx, y: ly, s, lens, under: refract(S.id, lx, ly, 1.04), overRot: -90 }),
  };
}

/* 3 — terminal --------------------------------------------------------- */
export function terminal() {
  const S = hstrip({ id: 'ts', P: 600, x0: 24.3, y0: 263.5, k0: -1, k1: 4, rot: -2, rcx: 960, rcy: 540 });
  const a = S.fx(0) + 46, b = S.fx(1) + 46, y = S.fy;
  let c = '';
  c += T('code', a, y + 84, 30, '$ pnpm test', { op: 0.58 }) + T('disp', a - 3, y + 210, 76, '2 failed', { w: 800, ls: -1.5 }) + T('disp', a - 1, y + 288, 43, '12 passed', { w: 300, op: 0.62 });
  c += T('code', b, y + 84, 30, 'edit src/webhooks/', { op: 0.58 }) + T('disp', b - 3, y + 210, 70, 'send.ts', { w: 600, ls: -1.5 }) + T('disp', b - 1, y + 288, 43, '+18 −4', { w: 300, op: 0.62 });
  c += greek(S.fx(3) + 46, y + 70, 300, 300, 5, { bar: 16, op: 0.08, n: 4 });
  const ep = (k, t) => T('mono', S.fx(k) + 2, S.bottom - 9, 15, t, { op: 0.6, ls: 1 });
  c += ep(0, 'session 3 · entry 204 · 02:09') + ep(1, 'session 3 · entry 209 · 02:12') + ep(2, 'session 4 · entry 219 · 05:48');
  c += T('mono', S.fx(0) + 2, S.top + 20, 14, 'DAILIES SAFETY FILM', { op: 0.26, ls: 3.5 });
  const strip = S.open + S.body + c + S.close;
  const lx = S.cx(2), ly = S.yAt(lx), s = 1.3;
  const lens = `${lensLit}<g transform="rotate(-2)">${T('code', 0, -132, 34, '$ pnpm test', { anchor: 'middle', op: 0.66 })}${T('disp', 0, 38, 84, '14 passed', { w: 800, anchor: 'middle', ls: -1.5 })}${pencil(ringD(0, 8, 322, 96, { seed: 11, start: Math.PI * 0.86 }), { sw: 11 })}</g>`;
  return {
    label: 'Terminal. pnpm test: 2 failed, 12 passed. Then an edit to src/webhooks/send.ts. Then pnpm test: 14 passed, ringed in pencil under the loupe.',
    defs: bgDefs('tbg', lx, ly) + S.defs,
    body: bg('tbg') + strip + spill(lx, ly, 850) + loupe({ x: lx, y: ly, s, lens, under: refract(S.id, lx, ly) }),
  };
}

/* 4 — diff ------------------------------------------------------------- */
export const DIFF = [
  ['-', "  const res = await fetch(url, { method: 'POST', body });"],
  ['-', "  if (!res.ok) throw new Error('webhook failed');"],
  ['+', '  for (let attempt = 0; attempt < 4; attempt++) {'],
  ['+', "    const res = await fetch(url, { method: 'POST', body, signal: AbortSignal.timeout(5000) });"],
  ['+', '    if (res.ok) return;'],
  ['+', '    await sleep(250 * 2 ** attempt);'],
  ['+', '  }'],
  ['+', '  throw new WebhookError(url, 4);'],
];
export function diff() {
  const lx = 980, ly = 540, s = 2.75;
  const S = hstrip({ id: 'ds', P: 1500, x0: 230, y0: -151, k0: -1, k1: 1, rot: -2, rcx: 960, rcy: 540, frame: '#101816' });
  const F = 35, cw = F * 0.6, x0 = -625, y1 = -176, lh = 62;
  const rows = [
    ['-', "  const res = await fetch(url, { method: 'POST', body });"],
    ['-', "  if (!res.ok) throw new Error('webhook failed');"],
    ['+', '  for (let attempt = 0; attempt < 4; attempt++) {'],
    ['+', "    const res = await fetch(url, { method: 'POST', body,"],
    [' ', '        signal: AbortSignal.timeout(5000) });'],
    ['+', '    if (res.ok) return;'],
    ['+', '    await sleep(250 * 2 ** attempt);'],
    ['+', '  }'],
    ['+', '  throw new WebhookError(url, 4);'],
  ];
  let code = `<rect x="${x0 - 30}" y="${y1 + 2 * lh - 43}" width="1500" height="${7 * lh + 2}" fill="#eef3f1" opacity=".05"/>`;
  rows.forEach(([m, t], i) => {
    const rem = m === '-';
    code += T('code', x0, y1 + i * lh, F, esc(m + t), { w: rem ? 400 : 500, op: rem ? 0.42 : 0.96, extra: 'style="white-space:pre"' });
  });
  const ring1 = ringD(x0 + 30.5 * cw, y1 + 2 * lh - 11, 5.5 * cw + 17, 37, { seed: 4, start: Math.PI * 0.8, wob: 0.025 });
  const ring2 = ringD(x0 + 26 * cw, y1 + 6 * lh - 11, 9 * cw + 15, 37, { seed: 9, start: Math.PI * 0.82, wob: 0.025 });
  const hy = y1 - 104;
  const head = T('code', x0, hy, 33, 'src/webhooks/', { op: 0.6 }) + T('disp', x0 + 13 * 19.8 + 10, hy, 70, 'send.ts', { w: 600, ls: -1.5 }) + T('disp', 560, hy, 70, '+18 −4', { w: 300, anchor: 'end', ls: -1 });
  const lens = `${lensLit}<g transform="rotate(-1)">${head}${code}${pencil([ring1, ring2], { sw: 9 })}</g>`;
  return {
    label: 'Diff. src/webhooks/send.ts, plus 18 minus 4. The loop condition attempt < 4 and the backoff 250 * 2 ** attempt are ringed in pencil.',
    defs: bgDefs('dbg', lx, ly) + S.defs,
    body: bg('dbg') + S.open + S.body + S.close + loupe({ x: lx, y: ly, s, lens, under: refract(S.id, lx, ly, 1.03), overRot: -90 }),
  };
}

/* 5 — stats ------------------------------------------------------------ */
export function stats() {
  const S = hstrip({ id: 'ss', P: 384, x0: 0, y0: 186, k0: -1, k1: 5, half: true, rot: -2, rcx: 960, rcy: 540 });
  const items = [['4', 'sessions'], ['9', 'commits'], ['212', 'tool calls'], ['96', 'minutes'], ['48k', 'output tokens']];
  let c = '';
  const at = [S.cx(0), 500, 960, 1420, S.cx(4)];
  items.forEach(([n, l], k) => {
    if (k === 2) return;
    c += T('disp', at[k], S.fy + 258, 100, n, { w: 800, anchor: 'middle', ls: -2.5, fill: '#dfe6e3' }) + T('txt', at[k], S.fy + 330, 38, l, { w: 600, anchor: 'middle', fill: '#c3cfca' });
  });
  c += T('mono', 24, S.top + 30, 20, 'acme/api', { op: 0.75, ls: 1.5 }) + T('mono', 24 + 170, S.top + 30, 20, 'last night, 23:40 – 06:10', { op: 0.45, ls: 1.5 });
  c += T('mono', 1896, S.bottom - 12, 20, 'DAILIES SAFETY FILM', { op: 0.26, ls: 4, anchor: 'end' });
  const strip = S.open + S.body + c + S.close;
  const lx = 960, ly = 540, s = 1;
  const lens = `${lensLit}<g transform="rotate(-2)">${T('disp', 0, 44, 188, '212', { w: 800, anchor: 'middle', ls: -5 })}${T('txt', 0, 128, 52, 'tool calls', { w: 600, anchor: 'middle', fill: '#dfe6e3' })}</g>`;
  return {
    label: 'Stats. 4 sessions, 9 commits, 212 tool calls, 96 minutes, 48k output tokens.',
    defs: bgDefs('sbg', lx, ly) + S.defs,
    body: bg('sbg') + strip + spill(lx, ly, 700) + loupe({ x: lx, y: ly, s, lens, under: refract(S.id, lx, ly) }),
  };
}

/* 6 — flag ------------------------------------------------------------- */
export function flag() {
  const S = hstrip({ id: 'fs', P: 803, x0: 129, y0: 140, k0: -1, k1: 2, rot: -2, rcx: 960, rcy: 510, fills: { '-1': '#0f1614', 2: '#0f1614' } });
  let c = `<g fill="#eef3f1" opacity=".08"><rect x="1800" y="330" width="90" height="16" rx="8"/><rect x="1800" y="372" width="60" height="16" rx="8"/><rect x="-10" y="330" width="80" height="16" rx="8"/><rect x="-10" y="372" width="100" height="16" rx="8"/></g>`;
  c += T('mono', 196, 338, 28, 'the agent said', { op: 0.55 });
  c += pencil(crossD(530, 540, 716, 356, { seed: 3 }), { sw: 16 });
  c += `<text class="disp" font-size="82" font-weight="600" fill="#dfe6e3" letter-spacing="-2.5" stroke="#131c19" stroke-width="11" stroke-linejoin="round" paint-order="stroke"><tspan x="190" y="478">“All 14</tspan><tspan x="190" y="584">tests pass.”</tspan></text>`;
  c += T('mono', 152, 869, 26, 'session 3 · entry 212', { op: 0.8, ls: 1 }) + T('mono', 152, 174, 22, 'DAILIES SAFETY FILM   211', { op: 0.26, ls: 5 });
  const strip = S.open + S.body + c + S.close;
  const lx = 1333, ly = 497, s = 1.152;
  const lens = `${lensLit}<g transform="rotate(-2)"><g fill="#eef3f1" opacity=".16"><rect x="-173" y="-246" width="173" height="13" rx="6.5"/><rect x="-173" y="-216" width="265" height="13" rx="6.5"/><rect x="-136" y="198" width="219" height="13" rx="6.5"/><rect x="-136" y="228" width="138" height="13" rx="6.5"/></g>${T('txt', 0, -120, 44.5, 'Last test run', { w: 600, anchor: 'middle', op: 0.94 })}${T('txt', 0, -67, 44.5, 'before this message:', { w: 600, anchor: 'middle', op: 0.94 })}${T('disp', 0, 72, 81, '2 failed.', { w: 800, anchor: 'middle', ls: -2.3 })}${pencil(ringD(0, 44, 284, 88, { seed: 7 }), { sw: 10 })}</g>`;
  const verdict = `<g transform="translate(905 806) rotate(-5)"><rect x="-322" y="-44" width="644" height="108" rx="54" fill="#000" opacity=".55" filter="url(#pillShadow)"/><rect x="-322" y="-54" width="644" height="108" rx="54" fill="#ffd60a"/>${T('disp', 0, 20, 54, 'CONTRADICTED', { w: 800, anchor: 'middle', fill: '#0d1211', ls: 1 })}</g>`;
  // the second flag, smaller
  const y2 = 994;
  const second = `${pencil(qD(178, y2 - 16, 66), { sw: 8, filter: 'pencil' })}${T('txt', 226, y2, 40, '“Deployed to staging.”', { w: 600, op: 0.92 })}<rect x="664" y="${y2 - 39}" width="224" height="52" rx="26" fill="none" stroke="#ffd60a" stroke-width="2.5"/>${T('disp', 776, y2 - 5, 21, 'UNVERIFIED', { w: 600, anchor: 'middle', fill: '#ffd60a', ls: 0.6 })}${T('txt', 918, y2, 36, 'No deploy command is recorded.', { fill: '#c3cfca' })}`;
  return {
    label: 'Flag. The agent said: All 14 tests pass. Contradicted. Last test run before this message: 2 failed. Source: session 3, entry 212. Second flag: Deployed to staging. Unverified. No deploy command is recorded.',
    defs: bgDefs('fbg', lx, ly) + S.defs,
    body: bg('fbg') + strip + spill(lx, ly, 760) + loupe({ x: lx, y: ly, s, lens, under: refract(S.id, lx, ly) }) + verdict + second,
  };
}

/* 7 — end -------------------------------------------------------------- */
export function end() {
  const yc = 571;
  const S = hstrip({ id: 'es', P: 146, x0: 88.4, y0: yc - 134.5, k0: -2, k1: 15, half: true, rot: -2, rcx: 960, rcy: yc, frame: '#18231f' });
  const order = ['v', 'v', 'v', 'v', 'v', 'x', 'v', 'q'];
  let c = '', marks = [];
  order.forEach((m, k) => {
    const cx = S.cx(k), cy = S.cy;
    c += greek(S.fx(k) + 16, S.fy + 22, S.fw - 30, 100, 70 + k, { bar: 6, op: 0.13 });
    if (m === 'v') marks.push(ringD(cx, cy, 43 + (k % 3) * 2, 55 - (k % 2) * 4, { seed: 20 + k, wob: 0.05, tilt: -0.1 + (k % 3) * 0.08 }));
    else if (m === 'x') marks.push(crossD(cx, cy, 104, 150, { seed: 5 }));
    else marks.push(qD(cx, cy - 2, 118));
  });
  for (let k = 8; k <= 15; k++) c += greek(S.fx(k) + 16, S.fy + 22, S.fw - 30, 100, 90 + k, { bar: 6, op: 0.05 });
  c += pencil(marks, { sw: 9, filter: 'pencil' });
  const strip = S.open + S.body + c + S.close;
  const lx = 1640, ly = S.yAt(1640), s = 1.1;
  const lens = `${lensLit}<g transform="rotate(-2)">${T('disp', -12, 36, 100, 'Dailies', { w: 800, anchor: 'middle', ls: -2 })}</g>`;
  const ty = 890;
  const tally = (x, kind, t) => {
    const m = kind === 'v' ? ringD(x + 26, ty - 15, 24, 22, { seed: 31, wob: 0.05 }) : kind === 'x' ? crossD(x + 26, ty - 15, 44, 44, { seed: 8 }) : qD(x + 26, ty - 16, 54);
    return pencil(m, { sw: 6.5, filter: 'pencil' }) + T('txt', x + 68, ty, 44, t, { w: 600 });
  };
  const text = T('disp', 90, 318, 150, 'acme/api', { w: 800, ls: -3 }) + tally(96, 'v', '6 claims verified') + tally(96 + 68 + 326 + 54, 'x', '1 contradicted') + tally(96 + 68 + 326 + 54 + 68 + 288 + 54, 'q', '1 unverified');
  return {
    label: 'End card. acme/api. 6 claims verified, 1 contradicted, 1 unverified. Dailies.',
    defs: bgDefs('ebg', lx, ly) + S.defs,
    body: bg('ebg') + strip + spill(lx, ly, 720) + loupe({ x: lx, y: ly, s, lens, under: refract(S.id, lx, ly) }) + text,
  };
}

export const svgFrame = (fr, attrs = '') => `<svg ${attrs} viewBox="0 0 1920 1080" role="img" aria-label="${fr.label}"><defs>${fr.defs}</defs>${fr.body}</svg>`;

