// Shared drawing helpers for the Loupe direction. Everything is emitted as static SVG/HTML at build time.

export const f = (n) => +(+n).toFixed(1);

export function rng(seed) {
  let a = (seed * 2654435761) >>> 0;
  return () => {
    a |= 0; a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function smooth(pts) {
  let d = `M${f(pts[0][0])},${f(pts[0][1])}`;
  for (let i = 0; i < pts.length - 1; i++) {
    const p0 = pts[Math.max(i - 1, 0)], p1 = pts[i], p2 = pts[i + 1], p3 = pts[Math.min(i + 2, pts.length - 1)];
    const c1 = [p1[0] + (p2[0] - p0[0]) / 6, p1[1] + (p2[1] - p0[1]) / 6];
    const c2 = [p2[0] - (p3[0] - p1[0]) / 6, p2[1] - (p3[1] - p1[1]) / 6];
    d += ` C${f(c1[0])},${f(c1[1])} ${f(c2[0])},${f(c2[1])} ${f(p2[0])},${f(p2[1])}`;
  }
  return d;
}

/* ---------- grease pencil geometry ---------- */

// A hand-drawn loop: starts at the left, goes over the top, and overshoots its own start.
export function ringD(cx, cy, rx, ry, o = {}) {
  const { seed = 1, turns = 1.15, start = Math.PI * 0.97, wob = 0.035, tilt = -0.05, drift = -0.1, steps = 30 } = o;
  const r = rng(seed * 7919 + 13);
  const h1 = r() * 6.28, h2 = r() * 6.28, a1 = wob * (0.7 + r() * 0.6), a2 = wob * 0.6 * (0.7 + r() * 0.6);
  const total = Math.PI * 2 * turns, pts = [];
  for (let i = 0; i <= steps; i++) {
    const t = i / steps, a = start + total * t;
    const k = 1 + a1 * Math.sin(a + h1) + a2 * Math.sin(a * 2.3 + h2) + drift * (t - 0.5);
    const x = Math.cos(a) * rx * k, y = Math.sin(a) * ry * k;
    pts.push([cx + x * Math.cos(tilt) - y * Math.sin(tilt), cy + x * Math.sin(tilt) + y * Math.cos(tilt)]);
  }
  return smooth(pts);
}

export function crossD(cx, cy, w, h, o = {}) {
  const { seed = 1 } = o;
  const r = rng(seed * 104729 + 7), j = (m) => (r() - 0.5) * m;
  const x1 = cx - w / 2, x2 = cx + w / 2, y1 = cy - h / 2, y2 = cy + h / 2;
  const a = `M${f(x1 + j(w * 0.05))},${f(y1 + j(h * 0.08))} C${f(cx - w * 0.2)},${f(cy - h * 0.2 + j(h * 0.1))} ${f(cx + w * 0.16)},${f(cy + h * 0.12 + j(h * 0.1))} ${f(x2 + j(w * 0.05))},${f(y2 + j(h * 0.08))}`;
  const b = `M${f(x2 + j(w * 0.05))},${f(y1 + j(h * 0.08))} C${f(cx + w * 0.18)},${f(cy - h * 0.16 + j(h * 0.1))} ${f(cx - w * 0.2)},${f(cy + h * 0.2 + j(h * 0.1))} ${f(x1 + j(w * 0.05))},${f(y2 + j(h * 0.08))}`;
  return a + ' ' + b;
}

// Question mark in a box `h` tall, centred on cx,cy.
export function qD(cx, cy, h) {
  const s = h / 100, P = (x, y) => `${f(cx + x * s)},${f(cy + y * s)}`;
  return `M${P(-23, -23)} C${P(-25, -57)} ${P(27, -59)} ${P(26, -27)} C${P(25, -6)} ${P(1, -5)} ${P(0, 19)} M${P(-1, 43)} L${P(1, 45)}`;
}

export function underD(x1, x2, y, o = {}) {
  const { seed = 1, amp = 4 } = o;
  const r = rng(seed * 31 + 5), n = 5, pts = [];
  for (let i = 0; i <= n; i++) pts.push([x1 + ((x2 - x1) * i) / n, y + (r() - 0.5) * amp * 2 - (i / n - 0.5) * amp * 1.5]);
  return smooth(pts);
}

// Wrap pencil paths. `filter` is one of pencil | pencilBig | pencilSm | none.
export function pencil(paths, o = {}) {
  const { sw = 8, filter = 'pencilBig', dash = '', pad = '', extra = '' } = o;
  const d = Array.isArray(paths) ? paths : [paths];
  return `<g fill="none" stroke="#ffd60a" stroke-width="${sw}" stroke-linecap="round" stroke-linejoin="round"${filter === 'none' ? '' : ` filter="url(#${filter})"`}${dash ? ` stroke-dasharray="${dash}"` : ''}${extra ? ' ' + extra : ''}>${pad ? `<path d="${pad}" stroke="none"/>` : ''}${d.map((p) => `<path d="${p}"/>`).join('')}</g>`;
}

/* ---------- verdict marks for UI (small, inline) ---------- */
// kind: verified | contradicted | stale | unverified
export function mark(kind, size = 28, o = {}) {
  const { sw = 4.6, seed = 3, cls = '' } = o;
  let inner;
  if (kind === 'verified') inner = `<path d="${ringD(24, 24, 17, 15.5, { seed, wob: 0.05, turns: 1.13 })}"/>`;
  else if (kind === 'stale') inner = `<path d="${ringD(24, 24, 17, 15.5, { seed, wob: 0.05, turns: 1.0, drift: 0 })}" stroke-dasharray="8.5 8"/>`;
  else if (kind === 'contradicted') inner = `<path d="${crossD(24, 24, 31, 31, { seed })}"/>`;
  else inner = `<path d="${qD(24, 23, 40)}"/>`;
  return `<svg class="mk mk-${kind}${cls ? ' ' + cls : ''}" width="${size}" height="${size}" viewBox="0 0 48 48" aria-hidden="true"><g fill="none" stroke="#ffd60a" stroke-width="${sw}" stroke-linecap="round" stroke-linejoin="round">${inner}</g></svg>`;
}

// A phrase ringed in pencil, robust to reflow: the SVG stretches to the span's box.
export function ringSpan(text, o = {}) {
  const { seed = 5, sw = 3.2, cls = '', filter = 'pencilSm' } = o;
  return `<span class="pr${cls ? ' ' + cls : ''}">${text}<svg viewBox="0 0 300 100" preserveAspectRatio="none" aria-hidden="true"><path d="${ringD(150, 50, 138, 40, { seed, wob: 0.03, tilt: -0.015, turns: 1.07, drift: -0.05, start: Math.PI * 0.9 })}" fill="none" stroke="#ffd60a" stroke-width="${sw}" stroke-linecap="round" vector-effect="non-scaling-stroke"${filter === 'none' ? '' : ` filter="url(#${filter})"`}/></svg></span>`;
}

/* ---------- film ---------- */

// Horizontal strip. Default frames are 8-perf landscape (3:2); half:true gives 4-perf portrait half-frames.
export function hstrip(o) {
  const { id, P, x0, y0, k0 = -1, k1 = 4, rot = -2, rcx = 960, rcy = 540, half = false, fills = {}, base = '#070a09', perf = '#1c2724', frame = '#131c19' } = o;
  const U = half ? P * 2 : P;
  const H = 0.9215 * U, pw = 0.0523 * U, ph = 0.0735 * U, cell = U / 8, gap = 0.0523 * U;
  const fy = y0 + 0.1445 * U, fh = 0.6314 * U, fw = P - gap;
  const X0 = x0 + k0 * P - 400, X1 = x0 + (k1 + 1) * P + 400;
  const fx = (k) => x0 + k * P + gap / 2;
  let rects = '';
  for (let k = k0; k <= k1; k++) rects += `<rect x="${f(fx(k))}" y="${f(fy)}" width="${f(fw)}" height="${f(fh)}" rx="${f(Math.max(3, U * 0.0105))}" fill="${fills[k] || frame}"/>`;
  const open = `<g id="${id}" transform="rotate(${rot} ${rcx} ${rcy})">`;
  const body = `<rect x="${f(X0)}" y="${f(y0)}" width="${f(X1 - X0)}" height="${f(H)}" fill="${base}"/><rect x="${f(X0)}" y="${f(y0)}" width="${f(X1 - X0)}" height="${f(H)}" fill="url(#${id}P)"/><path d="M${f(X0)},${f(y0 + 1)}H${f(X1)}M${f(X0)},${f(y0 + H - 1)}H${f(X1)}" stroke="#eef3f1" stroke-opacity=".16" stroke-width="2"/>${rects}`;
  const defs = `<pattern id="${id}P" patternUnits="userSpaceOnUse" x="${f(x0)}" y="${f(y0)}" width="${f(cell)}" height="${f(H)}"><rect x="${f((cell - pw) / 2)}" y="${f(0.0523 * U)}" width="${f(pw)}" height="${f(ph)}" rx="${f(U * 0.01)}" fill="${perf}"/><rect x="${f((cell - pw) / 2)}" y="${f(H - 0.0523 * U - ph)}" width="${f(pw)}" height="${f(ph)}" rx="${f(U * 0.01)}" fill="${perf}"/></pattern>`;
  return { id, open, body, close: '</g>', defs, fx, fy, fw, fh, H, y0, P, U, cx: (k) => fx(k) + fw / 2, cy: fy + fh / 2, top: y0, bottom: y0 + H, rot, rcx, rcy,
    // y of the strip centre line at screen x, after rotation
    yAt: (x) => y0 + H / 2 + (x - rcx) * Math.tan((rot * Math.PI) / 180) - (y0 + H / 2 - rcy) * (1 - Math.cos((rot * Math.PI) / 180)) };
}

// Greeked content for an unlit frame: a few soft bars.
export function greek(x, y, w, h, seed, o = {}) {
  const { bar = 9, op = 0.1, n } = o;
  const r = rng(seed * 97 + 3);
  const rows = n || 3 + Math.floor(r() * 3);
  let s = '';
  for (let i = 0; i < rows; i++) {
    const bw = w * (0.25 + r() * 0.55);
    s += `<rect x="${f(x)}" y="${f(y + i * bar * 2.4)}" width="${f(bw)}" height="${f(bar)}" rx="${f(bar / 2)}" fill="#eef3f1" opacity="${(op * (0.6 + r() * 0.8)).toFixed(2)}"/>`;
  }
  return s;
}

/* ---------- the loupe ---------- */
// Drawn around 0,0 with a 276 lens, 362 outer radius, then scaled by s.
// lens: SVG in real (unscaled) pixels relative to the loupe centre. under: refracted content for the clear skirt, same space.
export function loupe(o) {
  const { x, y, s = 1, lens = '', under = '', lensBg = '#2a3f38', overRot = 0, small = false, shadow = true } = o;
  const inv = f(1000 / s) / 1000;
  const real = (c) => (c ? `<g transform="scale(${(1 / s).toFixed(4)})">${c}</g>` : '');
  return `<g transform="translate(${f(x)} ${f(y)}) scale(${s})">${shadow ? '<use href="#loupeUnder"/>' : ''}<g clip-path="url(#skirtClip)"><circle r="364" fill="#17201d"/>${real(under)}<circle r="364" fill="#eef3f1" opacity=".1"/></g><use href="#loupeSkirt"/><g clip-path="url(#lensClip)"><circle r="278" fill="${lensBg}"/>${real(lens)}</g>${overRot ? `<use href="#loupeGlass"/><use href="#loupeBarrel"/><use href="#loupeEngr" transform="rotate(${overRot})"/>` : `<use href="#${small ? 'loupeOverSm' : 'loupeOver'}"/>`}</g>`;
}
// Refraction of a strip group through the skirt of a loupe at x,y.
export const refract = (id, x, y, m = 1.07, dx = 6, dy = -4) => `<use href="#${id}" transform="scale(${m}) translate(${f(-x + dx)} ${f(-y + dy)})"/>`;

export const esc = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

